// ResetPassword is the resolver for the resetPassword field.
func (r *mutationResolver) ResetPassword(ctx context.Context, input model.ResetPasswordInput) (*model.ResetPasswordResponse, error) {
	// Clean email
	email := strings.TrimSpace(strings.ToLower(input.Email))

	// Validate passwords
	if input.NewPassword != input.ConfirmPassword {
		return &model.ResetPasswordResponse{
			Success: false,
			Message: "Passwords do not match",
			IsReset: false,
		}, nil
	}

	if len(input.NewPassword) < 8 {
		return &model.ResetPasswordResponse{
			Success: false,
			Message: "Password must be at least 8 characters long",
			IsReset: false,
		}, nil
	}

	// Initialize OTP service
	otpService := otp.NewOtpService(r.RedisClient)

	// Verify OTP
	isValid, err := otpService.VerifyOTP(ctx, email, input.Otp)
	if err != nil {
		return &model.ResetPasswordResponse{
			Success: false,
			Message: fmt.Sprintf("OTP verification failed: %v", err),
			IsReset: false,
		}, nil
	}

	if !isValid {
		return &model.ResetPasswordResponse{
			Success: false,
			Message: "Invalid or expired OTP",
			IsReset: false,
		}, nil
	}

	if input.Type == string(model.UserTypeUser) {
		var user model.User
		if err := r.DB.Where("email = ?", email).First(&user).Error; err != nil {
			return &model.ResetPasswordResponse{
				Success: false,
				Message: "No user account found with this email",
				IsReset: false,
			}, nil
		}

		// Update user password
		hashedPassword, err := bcrypt.GenerateFromPassword([]byte(input.NewPassword), bcrypt.DefaultCost)
		if err != nil {
			log.Printf("Error hashing password: %v", err)
			return &model.ResetPasswordResponse{
				Success: false,
				Message: "Failed to update password",
				IsReset: false,
			}, nil
		}

		passwordStr := string(hashedPassword)
		user.Password = &passwordStr

		if err := r.DB.Save(&user).Error; err != nil {
			log.Printf("Error updating user password: %v", err)
			return &model.ResetPasswordResponse{
				Success: false,
				Message: "Failed to update password",
				IsReset: false,
			}, nil
		}

		return &model.ResetPasswordResponse{
			Success: true,
			Message: "Password reset successfully",
			IsReset: true,
			Email:   &email,
		}, nil
	} else if input.Type == model.UserTypeService.String() {
		var service model.Service
		if err := r.DB.Where("email = ?", email).First(&service).Error; err != nil {
			return &model.ResetPasswordResponse{
				Success: false,
				Message: "No service account found with this email",
				IsReset: false,
			}, nil
		}

		// Update service password
		hashedPassword, err := bcrypt.GenerateFromPassword([]byte(input.NewPassword), bcrypt.DefaultCost)
		if err != nil {
			log.Printf("Error hashing password: %v", err)
			return &model.ResetPasswordResponse{
				Success: false,
				Message: "Failed to update password",
				IsReset: false,
			}, nil
		}

		passwordStr := string(hashedPassword)
		service.Password = &passwordStr

		// Update authentication status if needed
		if service.IsAuth != nil && *service.IsAuth != model.IsAuthAuthenticated {
			authStatus := model.IsAuthAuthenticated
			service.IsAuth = &authStatus
		}

		if err := r.DB.Save(&service).Error; err != nil {
			log.Printf("Error updating service password: %v", err)
			return &model.ResetPasswordResponse{
				Success: false,
				Message: "Failed to update password",
				IsReset: false,
			}, nil
		}

		return &model.ResetPasswordResponse{
			Success: true,
			Message: "Password reset successfully",
			IsReset: true,
			Email:   &email,
		}, nil
	} else {
		return &model.ResetPasswordResponse{
			Success: false,
			Message: "Invalid user type",
			IsReset: false,
		}, nil
	}
}
